#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum AxisAccessVerdict {
    AxisAccessAdmitted {
        authority: Rc<ExternalAuthority>,
    },
    AxisAccessRefusedByAuthority {
        authority: Rc<ExternalAuthority>,
    },
    AxisAccessUnjudged {
        read_obligation: NonEmptyStr,
    },
}

pub fn permission_axis_access_verdict(axis: GitHubPermissionAxis, access: GitHubAppPermissionAccess) -> Rc<AxisAccessVerdict> {
    match (*permission_axis_admitted_accesses(axis)).clone() {
    AxisAccessAdmission::AxisAccessesUnread { read_obligation: o, .. } => Rc::new(AxisAccessVerdict::AxisAccessUnjudged {
    read_obligation: o.clone(),
}),
    AxisAccessAdmission::AxisAdmitsExactly { set: st, authority: auth, .. } => if github_access_set_admits(st.clone(), access) {
        Rc::new(AxisAccessVerdict::AxisAccessAdmitted {
    authority: auth.clone(),
})
    } else {
        Rc::new(AxisAccessVerdict::AxisAccessRefusedByAuthority {
    authority: auth.clone(),
})
    },
}
}

pub fn first_permission_not_admitted(perms: Rc<Vec<Rc<GitHubAppPermission>>>) -> Option<Rc<GitHubAppPermission>> {
    crate::std_algebra::fold_list(perms, std::option::Option::None, |found, p| match found.clone() {
    Some(v) => Some(v.clone()),
    std::option::Option::None => match (*permission_axis_access_verdict(p.name.clone(), p.access.clone())).clone() {
    AxisAccessVerdict::AxisAccessAdmitted { authority: _, .. } => std::option::Option::None,
    AxisAccessVerdict::AxisAccessUnjudged { read_obligation: _, .. } => std::option::Option::None,
    AxisAccessVerdict::AxisAccessRefusedByAuthority { authority: _, .. } => Some(p.clone()),
},
})
}

pub fn permission_access_wire_name(access: GitHubAppPermissionAccess) -> String {
    match access.clone() {
    GitHubAppPermissionAccess::AppAccessRead => "read".to_string(),
    GitHubAppPermissionAccess::AppAccessWrite => "write".to_string(),
}
}

pub fn permission_access_from_wire(name: String) -> Option<GitHubAppPermissionAccess> {
    if (name.clone() == permission_access_wire_name(GitHubAppPermissionAccess::AppAccessRead)) {
        Some(GitHubAppPermissionAccess::AppAccessRead)
    } else {
        if (name.clone() == permission_access_wire_name(GitHubAppPermissionAccess::AppAccessWrite)) {
            Some(GitHubAppPermissionAccess::AppAccessWrite)
        } else {
            std::option::Option::None
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum ObservedPermissionMapDecode {
    ObservedPermissionsDecoded {
        permissions: Rc<Vec<Rc<ObservedGitHubPermission>>>,
    },
    ObservedPermissionAccessUnreadable {
        wire_name: NonEmptyStr,
        access: String,
    },
    ObservedPermissionKeyUnanswered {
        wire_name: NonEmptyStr,
    },
}

pub fn observed_permissions_from_wire_map(m: Rc<HashMap<String, String>>) -> Rc<ObservedPermissionMapDecode> {
    crate::std_algebra::fold_list(Rc::new(v1_rt::map_keys(&m)), Rc::new(ObservedPermissionMapDecode::ObservedPermissionsDecoded {
    permissions: Rc::new(vec![]),
}), |acc, key| match (*acc.clone()).clone() {
    ObservedPermissionMapDecode::ObservedPermissionAccessUnreadable { wire_name, access, .. } => Rc::new(ObservedPermissionMapDecode::ObservedPermissionAccessUnreadable {
    wire_name: wire_name.clone(),
    access: access.clone(),
}),
    ObservedPermissionMapDecode::ObservedPermissionKeyUnanswered { wire_name: wire_name, .. } => Rc::new(ObservedPermissionMapDecode::ObservedPermissionKeyUnanswered {
    wire_name: wire_name.clone(),
}),
    ObservedPermissionMapDecode::ObservedPermissionsDecoded { permissions: permissions, .. } => match v1_rt::lookup(&m, key.clone()) {
    std::option::Option::None => Rc::new(ObservedPermissionMapDecode::ObservedPermissionKeyUnanswered {
    wire_name: key.clone(),
}),
    Some(raw) => match permission_access_from_wire(raw.clone()) {
    std::option::Option::None => Rc::new(ObservedPermissionMapDecode::ObservedPermissionAccessUnreadable {
    wire_name: key.clone(),
    access: raw.clone(),
}),
    Some(access) => Rc::new(ObservedPermissionMapDecode::ObservedPermissionsDecoded {
    permissions: v1_rt::concat(permissions.clone(), Rc::new(vec![Rc::new(ObservedGitHubPermission {
    name: Rc::new(ObservedGitHubPermissionName {
    wire_name: key.clone(),
}),
    access: access.clone(),
})])),
}),
},
},
})
}

