pub fn repository_selection_wire_name(mode: GitHubAppRepositorySelectionMode) -> String {
    match mode.clone() {
    GitHubAppRepositorySelectionMode::SelectionAll => "all".to_string(),
    GitHubAppRepositorySelectionMode::SelectionSelected => "selected".to_string(),
}
}

pub fn repository_selection_from_wire(raw: String) -> Option<GitHubAppRepositorySelectionMode> {
    if (raw.clone() == repository_selection_wire_name(GitHubAppRepositorySelectionMode::SelectionAll)) {
        Some(GitHubAppRepositorySelectionMode::SelectionAll)
    } else {
        if (raw.clone() == repository_selection_wire_name(GitHubAppRepositorySelectionMode::SelectionSelected)) {
            Some(GitHubAppRepositorySelectionMode::SelectionSelected)
        } else {
            std::option::Option::None
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum InstallationRecordDecode {
    InstallationDecoded {
        installation: Rc<GitHubAppInstallation>,
    },
    InstallationSelectionUnreadable {
        raw: String,
    },
    InstallationPermissionsUnreadable {
        decode: Rc<ObservedPermissionMapDecode>,
    },
    InstallationSlugEmpty,
    InstallationHtmlUrlUnreadable {
        raw: String,
    },
}

pub fn installation_from_record(record: Rc<GitHubAppInstallationRecord>) -> Rc<InstallationRecordDecode> {
    match repository_selection_from_wire(record.repository_selection.clone()) {
    std::option::Option::None => Rc::new(InstallationRecordDecode::InstallationSelectionUnreadable {
    raw: record.repository_selection.clone(),
}),
    Some(selection) => match (*observed_permissions_from_wire_map(record.permissions.clone())).clone() {
    ObservedPermissionMapDecode::ObservedPermissionAccessUnreadable { wire_name: n, access: a, .. } => Rc::new(InstallationRecordDecode::InstallationPermissionsUnreadable {
    decode: Rc::new(ObservedPermissionMapDecode::ObservedPermissionAccessUnreadable {
    wire_name: n.clone(),
    access: a.clone(),
}),
}),
    ObservedPermissionMapDecode::ObservedPermissionKeyUnanswered { wire_name: n, .. } => Rc::new(InstallationRecordDecode::InstallationPermissionsUnreadable {
    decode: Rc::new(ObservedPermissionMapDecode::ObservedPermissionKeyUnanswered {
    wire_name: n.clone(),
}),
}),
    ObservedPermissionMapDecode::ObservedPermissionsDecoded { permissions: perms, .. } => if (record.app_slug.clone() == "".to_string()) {
        Rc::new(InstallationRecordDecode::InstallationSlugEmpty)
    } else {
        match crate::extdeps_uri::uri_from_wire(record.html_url.clone()) {
    std::option::Option::None => Rc::new(InstallationRecordDecode::InstallationHtmlUrlUnreadable {
    raw: record.html_url.clone(),
}),
    Some(html_url) => Rc::new(InstallationRecordDecode::InstallationDecoded {
    installation: Rc::new(GitHubAppInstallation {
    installation_id: GitHubAppInstallationId {
    value: record.id.clone(),
},
    app_id: GitHubAppId {
    value: record.app_id.clone(),
},
    app_slug: record.app_slug.clone(),
    html_url: html_url.clone(),
    account: record.account.clone(),
    repository_selection: selection.clone(),
    permissions: perms.clone(),
    subscribed_events: Rc::new({ let mut __result = Vec::new(); for e in record.events.clone().iter().cloned() { __result.push(e.clone()); } __result }),
}),
}),
}
    },
},
}
}

