pub fn installation_credential_of(token: String, expires_at: String, installation_id: i64, repositories: Rc<Vec<String>>, permissions: Rc<Vec<Rc<GitHubAppPermission>>>, acquisition: Rc<AcquisitionClockReading>) -> Rc<GitHubInstallationAcquisition> {
    {
        let validity = match (*crate::extdeps_time_rfc3339::rfc3339_parse_instant(expires_at)).clone() {
    Rfc3339InstantParse::Rfc3339InstantRefused { cause: c, .. } => Rc::new(CredentialValidity::ValidityUnestablished {
    cause: Rc::new(ValidityUnestablishedCause::ExpiryUndecodable {
    cause: c.clone(),
}),
}),
    Rfc3339InstantParse::Rfc3339InstantParsed { instant: expiry, .. } => crate::std_credentials::credential_validity_of(Rc::new(ValidityBasis::IssuerStated {
    stated_expiry: expiry.clone(),
    acquisition: acquisition.clone(),
})),
};
match first_duplicated_permission(permissions.clone()) {
    Some(dup) => Rc::new(GitHubInstallationAcquisition::GitHubInstallationPermissionAxisRepeated {
    axis: dup.name.clone(),
}),
    std::option::Option::None => Rc::new(GitHubInstallationAcquisition::GitHubInstallationAcquired {
    credential: Rc::new(GitHubInstallationCredential {
    secret_released_only_by_admission: token.clone(),
    binding: Rc::new(GitHubInstallationBinding {
    installation_id: installation_id.clone(),
    repositories: if (repositories.clone() == Rc::new(vec![])) {
            Rc::new(GitHubInstallationRepositorySelection::RepositoriesInstallationWide)
        } else {
            Rc::new(GitHubInstallationRepositorySelection::RepositoriesSelected {
    names: repositories.clone(),
})
        },
    permissions: if (permissions.clone() == Rc::new(vec![])) {
            Rc::new(GitHubInstallationPermissionSelection::PermissionsInstallationWide)
        } else {
            Rc::new(GitHubInstallationPermissionSelection::PermissionsSelected {
    permissions: permissions.clone(),
})
        },
}),
    validity: validity.clone(),
}),
}),
}
}
}

pub async fn acquire_scoped_installation_token(app_jwt: String, installation_id: i64, repositories: Rc<Vec<String>>, permissions: Rc<Vec<Rc<GitHubAppPermission>>>, net: &Network, clk: &Clock, github_app_installation_access_tokens: &Github__AppInstallationAccessTokens, clock: &Clock) -> std::result::Result<Rc<GitHubInstallationAcquisition>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match first_duplicated_permission(permissions.clone()) {
    Some(dup) => Rc::new(GitHubInstallationAcquisition::GitHubInstallationPermissionAxisRepeated {
    axis: dup.name.clone(),
}),
    std::option::Option::None => acquire_scoped_installation_token_unambiguous(app_jwt, installation_id, repositories, permissions.clone(), &net, &clk, github_app_installation_access_tokens, clock).await?,
})
}

pub async fn acquire_scoped_installation_token_unambiguous(app_jwt: String, installation_id: i64, repositories: Rc<Vec<String>>, permissions: Rc<Vec<Rc<GitHubAppPermission>>>, net: &Network, clk: &Clock, github_app_installation_access_tokens: &Github__AppInstallationAccessTokens, clock: &Clock) -> std::result::Result<Rc<GitHubInstallationAcquisition>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match (*crate::std_credentials::observe_acquisition_clock("github-installation-access-token".to_string(), &clk, clock).await?).clone() {
    AcquisitionClockRead::AcquisitionClockUnread { detail: d, .. } => Rc::new(GitHubInstallationAcquisition::GitHubInstallationClockUnread {
    detail: d.clone(),
}),
    AcquisitionClockRead::AcquisitionClockObserved { reading: acq, .. } => match (*github_app_installation_access_tokens.create_scoped(app_jwt.clone(), installation_id.clone(), repositories.clone(), github_installation_token_permissions(permissions.clone())).await?).clone() {
    RestResult::RestRefused { refusal: r, .. } => Rc::new(GitHubInstallationAcquisition::GitHubInstallationRefused {
    refusal: r.clone(),
}),
    RestResult::RestAnswered { answer: a, .. } => installation_credential_of(a.0.clone(), a.1.clone(), installation_id.clone(), repositories.clone(), permissions.clone(), acq.clone()),
},
})
}

